source('diagnostics/mimic/portable_lib.R');suppressPackageStartupMessages(library(ggplot2))
root<-mimic_root();out<-file.path(root,'reports');dir.create(file.path(out,'figures'),recursive=TRUE,showWarnings=FALSE)
m<-readr::read_csv(file.path(root,'aggregate/transport_metrics.csv'),show_col_types=FALSE)
z<-m |> dplyr::filter(score_cohort=='all',endpoint=='death_or_hospice',metric=='auc')
z$model<-factor(z$model,levels=c('baseline','phenotype','summaries','summaries_phenotype'),labels=c('Portable baseline','Baseline + phenotype','Baseline + respiratory summaries','Baseline + summaries + phenotype'))
z$subgroup<-factor(z$subgroup,levels=portable_spec()$subgroups,labels=c('Current hospitalization lung-cancer code (n=1,683)','Also prior completed lung-cancer encounter (n=673)'))
g<-ggplot(z,aes(estimate,model))+geom_vline(xintercept=.5,linetype=2,color='grey60')+geom_point(size=2,color='#176B87')+geom_errorbar(aes(xmin=conf_low,xmax=conf_high),orientation='y',width=.2,color='#176B87')+facet_wrap(~subgroup,ncol=1)+labs(x='External AUC (95% patient-bootstrap interval)',y=NULL,title='Frozen three-site models evaluated in MIMIC lung-cancer cohorts',subtitle='Hospital death/hospice within 28 days after ICU +72h; no MIMIC refitting',caption='POA is unavailable; all source periods included. Portable baseline excludes year and POA diagnosis covariates.\nNo room-air states or P1 assignments occur in this CLIF extract: four-phenotype coverage is incomplete.')+theme_minimal(base_size=11)+theme(plot.caption=element_text(hjust=0))
ggsave(file.path(out,'figures/external_auc.png'),g,width=11,height=7,dpi=180)
p<-readr::read_csv(file.path(root,'aggregate/support_profiles.csv'),show_col_types=FALSE)
p<-p |> tidyr::complete(phenotype,h=0:71,support=SUPPORT_STATES,fill=list(n_lower=0,n_upper=0)) |> dplyr::mutate(mid=(n_lower+n_upper)/2) |> dplyr::group_by(phenotype,h) |> dplyr::mutate(probability=mid/sum(mid)) |> dplyr::ungroup()
p$support<-factor(p$support,levels=SUPPORT_STATES)
g<-ggplot(p,aes(h,probability,fill=support))+geom_area(stat="identity")+facet_wrap(~phenotype,ncol=2)+scale_y_continuous(labels=function(x)paste0(round(100*x),'%'))+labs(x='Hours after first ICU arrival',y='Approximate support proportion',title='Support within frozen MIMIC assignments',subtitle='No P1 assignments: the source respiratory table contains no room-air labels',caption='Profiles reconstructed from count bands; I = insufficient/ambiguous/poor match. All eligible cases retained.\nWaterfall fills gaps using assumptions; it does not recover unrecorded room-air documentation.')+theme_minimal(base_size=11)+theme(legend.position='bottom',plot.caption=element_text(hjust=0),plot.margin=margin(12,16,12,40),axis.title.y=element_text(margin=margin(r=12)))
ggsave(file.path(out,'figures/support_profiles.png'),g,width=11,height=7,dpi=180)
